{
  "name": "Digit DP with Modular Divisibility and Restricted Digit Sets",
  tags: ["digit-dp", "divisibility", "restricted-digits", "counting", "dynamic-programming", "modular-arithmetic"],
  "description": "When counting natural numbers whose number of digits does not a given bound, whose digits are drawn from a finite digit set, and whose value is divisible by a small modulus, use digit-by-digit dynamic programming. The DP state tracks the remainder of the processed prefix (either digit sum or numeric value) modulo the modulus, transitioning digit by digit. The transition coefficients are determined by the contribution of each digit in the allowed set modulo the modulus. A critical distinction is made between counting strings that allow leading zeros and counting true natural numbers: the first digit cannot be zero. The correction is: the count of valid natural numbers of exact length L equals the count of valid strings of length L minus the count of valid strings of length L−1. Finally, decide whether to include the number 0 itself according to the problem statement. Common pitfalls include omitting leading-zero handling (causing numbers with leading zero to be miscounted), failing to consider whether 0 satisfies the condition, enumerating strings directly without grouping by remainder (causing state explosion), and off-by-one errors when summing over lengths from 1 to the upper bound.",
  applicability: [
    "The problem involves a restricted digit set.",
    "The number must be divisible by a small integer (typically single-digit modulus).",
    "The number of digits is bounded (e.g., at most a given length).",
    "All three elements—restricted digits, divisibility by a small integer, and digit-length bound—are present."
  ],
  steps: [
    {
      "step": "Identify the three key elements and confirm digit DP applicability",
      "detail": "Check for: (1) digits drawn from a finite set D, (2) divisibility condition n ≡ 0 (mod m) where m is small (usually single-digit), and (3) a bound on the number of digits. When all three appear, digit DP is the indicated strategy."
    },
    {
      "step": "Define the DP state using remainder modulo m",
      "detail": "Let dp[pos][r] represent the number of ways to fill the first pos positions such that the processed prefix (interpreted as a number or digit sum, depending on the problem) has remainder r modulo m. Because m is small, using remainder as a state dimension is feasible."
    },
    {
      "step": "Precompute transition coefficients by remainder class",
      "detail": "For each digit d in the allowed set D, compute d mod m. If multiple digits share the same remainder, count their occurrences. Let cnt[t] be the number of digits in D with t ≡ d (mod m). Transitions use these counts to compress the state transition: from remainder r, appending a digit with remainder t leads to new remainder (r·10 + t) mod m (or the appropriate update rule for the specific problem), weighted by cnt[t]."
    },
    {
      "step": "Perform digit-by-digit DP for strings allowing leading zeros",
      "detail": "Run the DP over positions 1 through L, allowing any digit from D at each position (including 0 at the first position). This counts all strings of length L over D whose numeric value satisfies the divisibility condition."
    },
    {
      "step": "Convert string counts to natural number counts by removing leading-zero cases",
      "detail": "For exact length L, the count of valid natural numbers is: count_strings(L) − count_strings(L−1). This subtracts strings whose first digit is zero (which correspond to shorter-length strings). Ensure the first digit of a true natural number is non-zero."
    },
    {
      "step": "Handle the number 0 according to problem conventions",
      "detail": "After computing counts for lengths 1 through the upper bound, check whether 0 itself satisfies the divisibility condition and whether the problem includes 0 in the set of natural numbers. Add or remove it accordingly."
    },
    {
      "step": "Sum over lengths and verify boundary conditions",
      "detail": "If the problem asks for numbers with at most L digits, sum the natural-number counts for lengths 1 to L. Carefully check boundaries to avoid off-by-one errors when accumulating partial sums."
    }
  ],
  example: {
    "problem": "Count natural numbers with at most 3 digits, using only digits from {0, 1, 2}, that are divisible by 3.",
    "solution": "Let D = {0,1,2} and m = 3. Precompute cnt[0]=1 (digit 0), cnt[1]=1 (digit 1), cnt[2]=1 (digit 2). Run DP for strings of length 1, 2, 3 allowing leading zeros. For length L, dp[L][0] gives strings divisible by 3. Then natural numbers of exact length L are dp[L][0] − dp[L−1][0]. Sum for L=1,2,3. Finally check if 0 should be included (0 is divisible by 3; include only if the problem counts 0 as a natural number)."
  }
}
